// engine.drawpixel (run without screen refresh)
void Glue3DSprite::EngineDrawpixel()
{
    stage.engineScreenPixel = stage.engineDrawx.Num() + (stage.engineDrawy.Num() * stage.engineScreenChannelrow.Num() + (2 * stage.engineScreenChannel.Num()));
    stage.enginePrevPixelTimer = stage.screenRenderer.Item(stage.engineScreenPixel.Num() - 1 - (2 * stage.engineScreenChannel.Num()));
    stage.engineNextPixelTimer = stage.screenRenderer.Item(stage.engineScreenPixel.Num() + 1 - (2 * stage.engineScreenChannel.Num()));
    if ((Lt(stage.engineNextPixelTimer, stage.engineScreenTimestamp) || (!(Eq(stage.enginePrevPixelTimer, stage.engineScreenTimestamp) && (Eq(stage.screenRenderer.Item(stage.engineScreenPixel.Num() + (1 * stage.engineScreenChannel.Num())), stage.enginePrevBright) && Eq(stage.enginePrevPixel, stage.screenRenderer.Item(stage.engineScreenPixel)))))) && Eq(stage.screenRenderer.Item(stage.engineScreenPixel.Num() - (2 * stage.engineScreenChannel.Num())), stage.engineScreenTimestamp))
    {
        SetX(stage.engineDrawx.Num() * stage.engineStepx.Num() + stage.engineScreenTopleftx.Num());
        SetPenColor(stage.screenRenderer.Item(stage.engineScreenPixel));
        ChangePenParam(PenParam::Brightness, stage.screenRenderer.Item(stage.engineScreenPixel.Num() + (1 * stage.engineScreenChannel.Num())).Num());
    }
    else
    {
        SetPenParam(PenParam::Transparency, 100 * Num(Lt(stage.screenRenderer.Item(stage.engineScreenPixel.Num() - (2 * stage.engineScreenChannel.Num())), stage.engineScreenTimestamp)));
    }
    stage.enginePrevPixel = stage.screenRenderer.Item(stage.engineScreenPixel);
    stage.enginePrevBright = stage.screenRenderer.Item(stage.engineScreenPixel.Num() + (1 * stage.engineScreenChannel.Num()));
}

