// object.findcollision (surface) (object) (run without screen refresh)
void Glue3DSprite::ObjectFindcollisionSurface(Value object)
{
    if (Eq(stage.engineSeg2D, 1))
    {
        Object2dsegSurface(object);
        stage.tempTemp1 = stage.engineSurfaceintersect;
        stage.tempTemp2 = stage.engineSurfacey1;
    }
    else
    {
        stage.tempTemp1 = 0;
        stage.tempTemp2 = 0;
    }
    if (Eq(stage.engineTile2D, 1))
    {
        Object2dtileSurface(object);
    }
    stage.engineSurfaceintersect = Num(Eq(stage.engineSurfaceintersect, 1) || Eq(stage.tempTemp1, 1)) * 1;
    if (Eq(stage.engineSurfaceintersect, 1) && Eq(stage.tempTemp1, 1))
    {
        stage.engineSurfacey1 = stage.tempTemp2;
    }
}

// object.findcollision (hitbox) (object) (run without screen refresh)
