// Insert Data to file (FileName) , (DataType) (Data) (run without screen refresh)
void Glue3DSprite::InsertDataToFile(Value fileName, Value dataType, Value data)
{
    if (Gt(stage.engineFiles.Length(), 0))
    {
        stage.fileID = stage.engineFiles.IndexOf(fileName);
        stage.engineFiles.Replace(stage.fileID.Num() + 1, stage.engineFiles.Item(stage.fileID.Num() + 1).Num() + 2);
        stage.engineFiles.Insert(stage.fileID.Num() + 2, data);
        stage.engineFiles.Insert(stage.fileID.Num() + 2, dataType);
    }
    else
    {
        StartSound(u"Windows Vista Beta Exclamation"_s);
    }
}

// proccess.physics (run without screen refresh)
void Glue3DSprite::ProccessPhysics()
{
    DataRecall();
    if (Eq(stage.decodedElements.Item(2), u"dir_force"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"velx"_s, Nz(Cos(stage.dataVal1.Num() + 90)) * stage.dataVal2.Num(), u"add"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"velz"_s, Nz(Sin(stage.dataVal1.Num() + 90)) * stage.dataVal2.Num(), u"add"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"include_physics"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"physics"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"physics"_s, 0);
            InsertDataToObjectData(stage.scriptObject, u"velx"_s, 0);
            InsertDataToObjectData(stage.scriptObject, u"vely"_s, 0);
            InsertDataToObjectData(stage.scriptObject, u"velz"_s, 0);
            InsertDataToObjectData(stage.scriptObject, u"gravity"_s, 0.9);
            InsertDataToObjectData(stage.scriptObject, u"jumpheight"_s, 1.5);
            InsertDataToObjectData(stage.scriptObject, u"friction"_s, 0.85);
            InsertDataToObjectData(stage.scriptObject, u"bounce"_s, 0.1);
            InsertDataToObjectData(stage.scriptObject, u"stand"_s, 1);
            InsertDataToObjectData(stage.scriptObject, u"hitwall"_s, 1);
            InsertDataToObjectData(stage.scriptObject, u"horizontal_col"_s, u"true"_s);
            InsertDataToObjectData(stage.scriptObject, u"vertical_col"_s, u"true"_s);
            InsertDataToObjectData(stage.scriptObject, u"hitbox_x"_s, 1);
            InsertDataToObjectData(stage.scriptObject, u"hitbox_y"_s, 1);
            InsertDataToObjectData(stage.scriptObject, u"hitbox_z"_s, 1);
            InsertDataToObjectData(stage.scriptObject, u"prev_sector"_s, 0);
            InsertDataToObjectData(stage.scriptObject, u"prev_y"_s, 0);
        }
        else
        {
            TerminalPrint(u"physics already included!"_s, u""_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"hitbox"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"physics"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            TerminalPrint(u"physics not included!"_s, u""_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"hitbox_x"_s, stage.dataVal1, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"hitbox_y"_s, stage.dataVal2, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"hitbox_z"_s, stage.dataVal3, u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"hitbox_collision"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"physics"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            TerminalPrint(u"physics not included!"_s, u""_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"horizontal_col"_s, stage.dataVal1, u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"surface_collision"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"physics"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            TerminalPrint(u"physics not included!"_s, u""_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"vertical_col"_s, stage.dataVal1, u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"set_factors"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"physics"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            TerminalPrint(u"physics not included!"_s, u""_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"gravity"_s, stage.dataVal1, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"jumpheight"_s, stage.dataVal2, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"friction"_s, stage.dataVal3, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"bounce"_s, stage.dataVal4, u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"add_force"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"physics"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            TerminalPrint(u"physics not included!"_s, u""_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"vel"_s + stage.dataVal1.Str(), stage.dataVal2, u"add"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"on_floor"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        EditDataInObjectDataOperation(stage.scriptObject, u"stand"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, 1))
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, u"true"_s, u"set"_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, u"false"_s, u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"collided"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        EditDataInObjectDataOperation(stage.scriptObject, u"hitwall"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, 1))
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, u"true"_s, u"set"_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, u"false"_s, u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"physics_tick"_s))
    {
        if (Gt(stage.allClock, 1))
        {
            EngineObjectphysics();
        }
    }
}

