// Render Bone Tree (run without screen refresh)
void Glue3DSprite::RenderBoneTree()
{
    stage.engineObjectindex = 3;
    for (double i1 = 0, times1 = Round(Nz(stage.loadedBoneTree.Item(3).Num() / stage.engineBoneattributes.Num())); i1 < times1; i1++)
    {
        if (!Eq(stage.loadedBoneTree.Item(stage.engineObjectindex.Num() + 7), 0))
        {
            stage.indexIndex1 = stage.loadedBoneTree.IndexOf(stage.loadedBoneTree.Item(stage.engineObjectindex.Num() + 7).Str() + (u".b-"_s + stage.loadedBoneTree.Item(2).Str()));
        }
        else
        {
            stage.indexIndex1 = 0;
        }
        DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.loadedBoneTree.Item(stage.engineObjectindex.Num() + 8).Str() + u"."_s, u""_s, u"."_s, u""_s, u""_s);
        EngineUnsortedspriteCostumeSizeDirGbcIdBone(stage.loadedBoneTree.Item(stage.engineObjectindex.Num() + 1), stage.loadedBoneTree.Item(stage.engineObjectindex.Num() + 2), stage.loadedBoneTree.Item(stage.engineObjectindex.Num() + 3), u"_icon.point"_s, 0.5 + ((Nz(Sin(Timer() * 500)) * 0.1) * Num(Eq(stage.modelGroup.Str() + (u".b-"_s + stage.loadedBoneTree.Item(2).Str()), stage.loadedBoneTree.Item(stage.engineObjectindex.Num() + 8)))), 90, 50, 0, 90 * Num(Eq(stage.modelGroup.Str() + (u".b-"_s + stage.loadedBoneTree.Item(2).Str()), stage.loadedBoneTree.Item(stage.engineObjectindex.Num() + 8))), stage.decodedElements.Item(1), stage.loadedBoneTree.Item(2), stage.engineObjectindex, stage.indexIndex1);
        if (Eq(stage.engineClip, 0) && Gt(stage.indexIndex1, 0))
        {
            stage.indexIndex1 = stage.indexIndex1.Num() - 8;
            SetPenSize(4 * Num(Gt(7 / stage.engineNewz.Num(), 4)) + (Num(Lt(7 / stage.engineNewz.Num(), 4)) * Nz(7 / stage.engineNewz.Num())));
            SetPenColor(u"#ffffff"_s);
            SetPenParam(PenParam::Transparency, 65 * Num(Eq(stage.editorModelType, u"3d"_s)));
            PenDown();
            stage.indexIndex2 = stage.loadedBoneTree.IndexOf(stage.loadedBoneTree.Item(stage.indexIndex1.Num() + 7).Str() + (u".b-"_s + stage.loadedBoneTree.Item(2).Str()));
            EngineUnsortedspriteCostumeSizeDirGbcIdBone(stage.loadedBoneTree.Item(stage.indexIndex1.Num() + 1), stage.loadedBoneTree.Item(stage.indexIndex1.Num() + 2), stage.loadedBoneTree.Item(stage.indexIndex1.Num() + 3), u"_icon.bone"_s, 0, 90, 100, 0, 0, u""_s, stage.loadedBoneTree.Item(2), stage.indexIndex1, stage.indexIndex2);
            PenUp();
        }
        stage.engineObjectindex = stage.engineObjectindex.Num() + stage.engineBoneattributes.Num();
    }
}

