// proccess: interface (run without screen refresh)
void Glue3DSprite::ProccessInterface()
{
    DataRecall();
    if (Eq(stage.decodedElements.Item(2), u"set_ghost"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"ui-ghost"_s, stage.dataVal1, u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"set_id"_s))
    {
        if (Eq(stage.dataVal1, u"empty"_s))
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"ui-id"_s, u"_icon.empty"_s, u"set"_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"ui-id"_s, stage.dataVal1, u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"dir"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"rx"_s, stage.dataVal1, u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"scale"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"sx"_s, stage.dataVal1, u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"set_pos"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, stage.dataVal1, u"set"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"y"_s, stage.dataVal2, u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"clickable"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"ui-clickable"_s, stage.dataVal1, u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"clicked"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        if (Eq(stage.guiClickedelement, stage.scriptObject))
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, u"true"_s, u"set"_s);
            stage.guiClickedelement = u""_s;
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, u"false"_s, u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"get_mouse_axis"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        if (Eq(stage.dataVal1, u"x"_s))
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, MouseX(), u"set"_s);
        }
        else if (Eq(stage.dataVal1, u"y"_s))
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, MouseY(), u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"dir"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"rx"_s, stage.dataVal1, u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"text"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"ui-text"_s, stage.dataVal1, u"set"_s);
    }
}

// proccess: file (run without screen refresh)
void Glue3DSprite::ProccessFile()
{
    DataRecall();
    if (Eq(stage.decodedElements.Item(2), u"create_file"_s))
    {
        if (stage.engineFiles.Contains(stage.dataVal1.Str() + u".end"_s))
        {
            TerminalPrint(u"file \""_s + (stage.dataVal1.Str() + u"\" already exists!"_s), 15);
        }
        else
        {
            if (Eq(stage.dataVal2, u"true"_s))
            {
                stage.tempFiles.Add(stage.dataVal1);
            }
            CreateFolder(stage.dataVal1);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"delete_file"_s))
    {
        if (stage.engineFiles.Contains(stage.dataVal1.Str() + u".end"_s))
        {
            DeleteNameIfDataObject(u"file"_s, stage.engineFiles.IndexOf(stage.dataVal1), u""_s, u""_s);
        }
        else
        {
            TerminalPrint(u"file \""_s + (stage.dataVal1.Str() + u"\" doesn't exist."_s), 15);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"move_item"_s))
    {
        FileFindData(stage.dataVal1);
        if (Eq(stage.fileFound, 1))
        {
            if (Gt(stage.engineFiles.IndexOf(stage.dataVal2), 0))
            {
                TerminalPrint(u"move "_s + (stage.dataVal1.Str() + (u" to "_s + stage.dataVal2.Str())), 15);
                EditAddress(33, 0);
                Move(u"selectfile"_s, stage.engineFiles.IndexOf(stage.dataVal2), u""_s);
                Move(u"selectdata"_s, stage.fileLoadIndex.Num() - 1, u""_s);
                EditAddress(34, stage.fileFolderIndex);
                Move(u"move"_s, u""_s, u""_s);
            }
            else
            {
                TerminalPrint(u"file \""_s + (stage.dataVal2.Str() + u"\" doesn't exsist."_s), 15);
            }
        }
        else
        {
            TerminalPrint(u"item \""_s + (stage.dataVal1.Str() + u"\" doesn't exsist."_s), 15);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"copy_item"_s))
    {
        FileFindData(stage.dataVal1);
        if (Eq(stage.fileFound, 1))
        {
            if (Gt(stage.engineFiles.IndexOf(stage.dataVal2), 0))
            {
                TerminalPrint(u"copy "_s + (stage.dataVal1.Str() + (u" to "_s + (stage.dataVal2.Str() + (u" as "_s + stage.dataVal3.Str())))), 15);
                EditAddress(33, 1);
                Move(u"selectfile"_s, stage.engineFiles.IndexOf(stage.dataVal2), u""_s);
                Move(u"selectdata"_s, stage.fileLoadIndex.Num() - 1, u""_s);
                EditAddress(34, stage.fileFolderIndex);
                Move(u"move"_s, u""_s, stage.dataVal3);
            }
            else
            {
                TerminalPrint(u"file \""_s + (stage.dataVal2.Str() + u"\" doesn't exsist."_s), 15);
            }
        }
        else
        {
            TerminalPrint(u"item \""_s + (stage.dataVal1.Str() + u"\" doesn't exsist."_s), 15);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"delete_item"_s))
    {
        FileFindData(stage.dataVal1);
        if (Eq(stage.fileFound, 1))
        {
            DeleteNameIfDataObject(u"data"_s, stage.fileLoadIndex.Num() - 1, stage.fileFolderIndex, u""_s);
            TerminalPrint(u"file: "_s + (stage.fileFolderIndex.Str() + (u", item: "_s + stage.fileLoadIndex.Str())), 15);
        }
        else
        {
            TerminalPrint(u"item \""_s + (stage.dataVal1.Str() + u"\" doesn't exsist."_s), 15);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"create_item"_s))
    {
        if (Gt(stage.engineFiles.IndexOf(stage.dataVal3), 0))
        {
            if (Eq(stage.dataVal1, u"model"_s))
            {
                InsertDataToFile(stage.dataVal3, u"model"_s, stage.dataVal2.Str() + u",3d,"_s);
            }
            else
            {
                InsertDataToFile(stage.dataVal3, stage.dataVal1, stage.dataVal2.Str() + u","_s);
            }
        }
        else
        {
            TerminalPrint(u"file \""_s + (stage.dataVal3.Str() + u"\" doesn't exsist."_s), 15);
        }
    }
}

// proccess: time (run without screen refresh)
void Glue3DSprite::ProccessTime()
{
    if (Eq(stage.decodedElements.Item(2), u"halt"_s))
    {
        TerminalPrint(u"program halted"_s, -35);
        stage.scene.Replace(stage.objectIndex.Num() + 31, u"halt"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"timer"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, Timer(), u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"reset"_s))
    {
        ResetTimer();
        stage.timeTimer = Timer();
    }
    if (Eq(stage.decodedElements.Item(2), u"ticks"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, Mod(stage.engineTick.Num(), 999999), u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"ticks"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, Mod(Nz(Mod(stage.engineTick.Num(), 10000000)), 999999), u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"timer_factor"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, Timer() * stage.dataVal1.Num(), u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"tick_factor"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, Nz(Mod(stage.engineTick.Num(), 10000000)) * stage.dataVal1.Num(), u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"delta"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, stage.timeDelta, u"set"_s);
    }
}

// sort (value) (run without screen refresh)
void Glue3DSprite::Sort(Value value)
{
    stage.sortIndex = stage.tempSort.Length();
    while (!Lt(value, stage.tempSort.Item(stage.sortIndex)))
    {
        stage.sortIndex = stage.sortIndex.Num() + -1;
    }
    stage.tempSort.Insert(stage.sortIndex.Num() + 1, value);
}

// Edit address (address#) (Value) (run without screen refresh)
void Glue3DSprite::EditAddress(Value address, Value value)
{
    stage.ramEngineData.Replace((address.Num() - 1) * 2 + 2, value);
}

