// Soundclone (ID) (run without screen refresh)
void Glue3DSprite::Soundclone(Value iD)
{
    stage.indexIndex1 = stage.soundTab.IndexOf(iD) - 1;
    if (!Eq(stage.allCycle, stage.soundTab.Item(stage.indexIndex1.Num() + 5)))
    {
        SetVolume(0);
        DeleteThisClone();
    }
    if (Gt(stage.soundTab.Item(stage.indexIndex1.Num() + 6), 3000))
    {
        SetVolume(0);
        DeleteThisClone();
    }
    if (Eq(stage.soundTab.Item(stage.indexIndex1.Num() + 6), 0))
    {
        StartSound(stage.soundTab.Item(stage.indexIndex1.Num() + 2));
    }
    stage.soundTab.Replace(stage.indexIndex1.Num() + 6, stage.soundTab.Item(stage.indexIndex1.Num() + 6).Num() + 1);
    SetVolume(stage.soundTab.Item(stage.indexIndex1.Num() + 3).Num());
    SetSoundEffect(SoundEffect::Pitch, stage.soundTab.Item(stage.indexIndex1.Num() + 4).Num());
    SetSoundEffect(SoundEffect::Pan, 1 - stage.allStereo.Num());
}

// play sound (ID) sound name (sound name) (volume) (pitch) (run without screen refresh)
void Glue3DSprite::PlaySoundSoundName(Value iD, Value soundName, Value volume, Value pitch)
{
    allClone = iD;
    CreateClone();
    allClone = 0;
    stage.soundTab.Add(iD);
    stage.soundTab.Add(soundName);
    stage.soundTab.Add(volume);
    stage.soundTab.Add(pitch);
    stage.soundTab.Add(stage.allCycle);
    stage.soundTab.Add(0);
}

