// glue3D.renderAll (run without screen refresh)
void Glue3DSprite::Glue3DRenderAll()
{
    // EDITED: a built game always shows the fullscreen game view; the editor screen isn't compiled into it.
    if (BuildFlavor::IsEditor && Eq(stage.engineFullscreen, 0))
    {
        if (Eq(stage.ramEngineData.Item(76), u"configured"_s))
        {
            if (Eq(stage.editorTab, u"model"_s) && Eq(stage.modelLoaded, 0))
            {
                Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_gui.contrast"_s, 0, 0, 90, 100, 0, -100, 0, u""_s, u""_s, u""_s, u""_s, u""_s);
                EditorDragscreen(u""_s);
                Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_gui.screen"_s, -68, 100 + stage.guiMainMargin.Num(), -90, 100, 50, u""_s, u""_s, u""_s, u""_s, u""_s, u""_s, u""_s);
                Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_gui.screen"_s, -68, -100 - stage.guiMainMargin.Num(), 90, 100, 50, u""_s, u""_s, u""_s, u""_s, u""_s, u""_s, u""_s);
            }
            else if (Eq(stage.editorTab, u"script"_s) && Eq(stage.scriptLoaded, 0))
            {
                Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_gui.contrast"_s, 0, 0, 90, 100, 0, -100, 0, u""_s, u""_s, u""_s, u""_s, u""_s);
                EditorDragscreen(1);
                Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_gui.screen"_s, -68, 100 + stage.guiMainMargin.Num(), -90, 100, 50, u""_s, u""_s, u""_s, u""_s, u""_s, u""_s, u""_s);
                Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_gui.screen"_s, -68, -100 - stage.guiMainMargin.Num(), 90, 100, 50, u""_s, u""_s, u""_s, u""_s, u""_s, u""_s, u""_s);
            }
            else
            {
                EngineScreenRender(0);
            }
        }
        else
        {
            EngineDimensions(u""_s);
            Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_gui.contrast"_s, 0, 0, 90, 100, 0, -100, 0, u""_s, u""_s, u""_s, u""_s, u""_s);
            Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_gui.missing_render"_s, stage.engineScreenMidx, 0, 90, 50, 0, 0, 0, u""_s, u""_s, u""_s, 1, u""_s);
            Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_gui.screen"_s, -68, 100 + stage.guiMainMargin.Num(), -90, 100, 50, u""_s, u""_s, u""_s, u""_s, u""_s, u""_s, u""_s);
            Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_gui.screen"_s, -68, -100 - stage.guiMainMargin.Num(), 90, 100, 50, u""_s, u""_s, u""_s, u""_s, u""_s, u""_s, u""_s);
        }
        if (Eq(stage.allExportState, 0))
        {
            EditorScreen();
        }
    }
    else
    {
        EngineScreenRender(1);
        if (Eq(stage.allExportState, 0))
        {
            Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_icon.bsod"_s, -220, 160, 90, 50, 60, 0, 0, 1, u""_s, u""_s, u""_s, u"editor"_s);
            if (Eq(stage.guiClick, 1))
            {
                stage.engineFullscreen = 0;
            }
        }
    }
    if (Eq(stage.errorPopup, 1))
    {
        ElementError();
    }
}

// data.recall (run without screen refresh)
void Glue3DSprite::DataRecall()
{
    if (Eq(stage.decodedElements.Item(3), u"var"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, stage.decodedElements.Item(4), 0, u"read"_s);
        stage.dataVal1 = stage.dataReturn;
    }
    else
    {
        stage.dataVal1 = stage.decodedElements.Item(4);
    }
    if (Eq(stage.decodedElements.Item(6), u"var"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, stage.decodedElements.Item(7), 0, u"read"_s);
        stage.dataVal2 = stage.dataReturn;
    }
    else
    {
        stage.dataVal2 = stage.decodedElements.Item(7);
    }
    if (Eq(stage.decodedElements.Item(9), u"var"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, stage.decodedElements.Item(10), 0, u"read"_s);
        stage.dataVal3 = stage.dataReturn;
    }
    else
    {
        stage.dataVal3 = stage.decodedElements.Item(10);
    }
    if (Eq(stage.decodedElements.Item(12), u"var"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, stage.decodedElements.Item(13), 0, u"read"_s);
        stage.dataVal4 = stage.dataReturn;
    }
    else
    {
        stage.dataVal4 = stage.decodedElements.Item(13);
    }
    ApplyValueTypes(); // EDITED: global x, local x, var slot[2]
}

